package view;
import bus.insurance.InsuranceBUS;import java.awt.*;import java.time.format.DateTimeFormatter;import javax.swing.*;import javax.swing.table.DefaultTableModel;import model.auth.AuthenticatedSession;import model.insurance.InsuranceModels.Card;import view.component.UIStyle;
final class InsurancePanel extends JPanel{
 private static final DateTimeFormatter F=DateTimeFormatter.ofPattern("dd/MM/yyyy");private final AuthenticatedSession session;private final InsuranceBUS bus;private final JTextField search=new JTextField();private final JComboBox<String> filter=new JComboBox<>(new String[]{"Tất cả trạng thái","ChuaXacThuc","HopLe","HetHan","KhongHopLe","ChoXacMinh"});private final DefaultTableModel model=new DefaultTableModel(new Object[]{"Mã thẻ","Bệnh nhân","Nơi KCB","Thời hạn","Mức hưởng","Trạng thái","__row"},0){public boolean isCellEditable(int r,int c){return false;}};private final JTable table=new JTable(model);private final JPanel detail=new JPanel(new BorderLayout());private final JButton edit=new JButton("Chỉnh sửa");private Card hovered;
 InsurancePanel(AuthenticatedSession s,InsuranceBUS b){session=s;bus=b;setLayout(new BorderLayout(0,16));setBackground(MainFrame.PAGE);setBorder(BorderFactory.createEmptyBorder(25,28,30,28));add(header(),BorderLayout.NORTH);add(body(),BorderLayout.CENTER);edit.addActionListener(e->{if(hovered!=null)open(hovered);});load();}
 private JPanel header(){JPanel p=new JPanel(new BorderLayout());p.setOpaque(false);JPanel l=new JPanel();l.setOpaque(false);l.setLayout(new BoxLayout(l,BoxLayout.Y_AXIS));JLabel t=new JLabel("Bảo hiểm y tế");t.setFont(new Font("Segoe UI",Font.BOLD,25));t.setForeground(MainFrame.TEXT);JLabel d=new JLabel("Danh sách gọn — rê chuột vào thẻ để xem đầy đủ thông tin.");d.setForeground(MainFrame.MUTED);l.add(t);l.add(d);JButton add=new JButton("+ Thêm thẻ BHYT");UIStyle.primaryButton(add);add.setVisible(session.hasPermission("BN_SUA"));add.addActionListener(e->{new InsuranceDialog(SwingUtilities.getWindowAncestor(this),session,bus,null).setVisible(true);load();});p.add(l,BorderLayout.WEST);p.add(add,BorderLayout.EAST);return p;}
 private JPanel body(){JPanel o=new JPanel(new BorderLayout(14,0));o.setOpaque(false);JPanel list=new JPanel(new BorderLayout(0,12));list.setBackground(Color.WHITE);list.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createLineBorder(MainFrame.BORDER),BorderFactory.createEmptyBorder(16,16,16,16)));JPanel bar=new JPanel(new BorderLayout(8,0));bar.setOpaque(false);search.setPreferredSize(new Dimension(350,36));search.putClientProperty("JTextField.placeholderText","Tìm số thẻ, mã bệnh nhân, họ tên...");bar.add(search,BorderLayout.CENTER);bar.add(filter,BorderLayout.EAST);list.add(bar,BorderLayout.NORTH);table.setRowHeight(40);UIStyle.table(table);table.setAutoCreateRowSorter(true);table.getColumnModel().getColumn(6).setMinWidth(0);table.getColumnModel().getColumn(6).setMaxWidth(0);table.getColumnModel().getColumn(6).setWidth(0);table.addMouseMotionListener(new java.awt.event.MouseMotionAdapter(){public void mouseMoved(java.awt.event.MouseEvent e){int r=table.rowAtPoint(e.getPoint());if(r>=0)showDetail((Card)table.getValueAt(table.convertRowIndexToModel(r),6));}});list.add(new JScrollPane(table),BorderLayout.CENTER);search.addActionListener(e->load());filter.addActionListener(e->load());o.add(list,BorderLayout.CENTER);o.add(card(),BorderLayout.EAST);return o;}
 private JPanel card(){detail.setPreferredSize(new Dimension(330,0));detail.setBackground(Color.WHITE);detail.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createLineBorder(MainFrame.BORDER),BorderFactory.createEmptyBorder(0,0,12,0)));showEmpty();return detail;}
 private void showEmpty(){detail.removeAll();detail.add(head("HỒ SƠ BHYT","Chọn một dòng để xem chi tiết"),BorderLayout.NORTH);JLabel h=new JLabel("Rê chuột vào danh sách bên trái",SwingConstants.CENTER);h.setForeground(MainFrame.MUTED);detail.add(h,BorderLayout.CENTER);detail.revalidate();detail.repaint();}
 private JPanel head(String a,String b){JPanel h=new JPanel();h.setBackground(MainFrame.NAVY);h.setLayout(new BoxLayout(h,BoxLayout.Y_AXIS));h.setBorder(BorderFactory.createEmptyBorder(16,18,16,18));JLabel x=new JLabel(a);x.setForeground(Color.WHITE);x.setFont(new Font("Segoe UI",Font.BOLD,12));JLabel y=new JLabel(b);y.setForeground(new Color(190,215,226));h.add(x);h.add(Box.createVerticalStrut(4));h.add(y);return h;}
 private void showDetail(Card c){if(c==null||c==hovered)return;hovered=c;detail.removeAll();JPanel body=new JPanel();body.setBackground(Color.WHITE);body.setBorder(BorderFactory.createEmptyBorder(16,18,10,18));body.setLayout(new BoxLayout(body,BoxLayout.Y_AXIS));JLabel status=new JLabel(c.status());status.setOpaque(true);status.setBackground("HetHan".equals(c.status())?new Color(210,75,83):new Color(38,157,105));status.setForeground(Color.WHITE);status.setBorder(BorderFactory.createEmptyBorder(5,9,5,9));body.add(status);body.add(Box.createVerticalStrut(14));body.add(group("Thông tin thẻ",new String[]{"Số thẻ",safe(c.cardNumber()),"Tên trên thẻ",safe(c.nameOnCard()),"Mức hưởng",safe(c.coverage())+"%","Nơi KCB",safe(c.facility())}));body.add(Box.createVerticalStrut(12));body.add(group("Thời hạn",new String[]{"Từ ngày",fmt(c.fromDate()),"Đến ngày",fmt(c.toDate()),"Bệnh nhân",safe(c.patientId())+" - "+safe(c.patientName())}));JScrollPane scroll=new JScrollPane(body);scroll.setBorder(null);JPanel actions=new JPanel(new GridLayout(1,2,8,0));actions.setBackground(Color.WHITE);actions.setBorder(BorderFactory.createEmptyBorder(10,18,0,18));UIStyle.secondaryButton(edit);edit.setEnabled(session.hasPermission("BN_SUA"));JButton refresh=new JButton("Làm mới");UIStyle.secondaryButton(refresh);refresh.addActionListener(e->load());actions.add(refresh);actions.add(edit);detail.add(head(c.cardNumber(),c.patientName()),BorderLayout.NORTH);detail.add(scroll,BorderLayout.CENTER);detail.add(actions,BorderLayout.SOUTH);detail.revalidate();detail.repaint();}
 private JPanel group(String title,String[] data){JPanel p=new JPanel();p.setOpaque(false);p.setLayout(new BoxLayout(p,BoxLayout.Y_AXIS));JLabel h=new JLabel(title);h.setFont(new Font("Segoe UI",Font.BOLD,12));h.setForeground(MainFrame.TEXT);p.add(h);p.add(Box.createVerticalStrut(7));for(int i=0;i<data.length;i+=2){JPanel r=new JPanel(new BorderLayout(8,0));r.setOpaque(false);JLabel k=new JLabel(data[i]);k.setForeground(MainFrame.MUTED);JLabel v=new JLabel("<html>"+data[i+1]+"</html>");v.setForeground(MainFrame.TEXT);r.add(k,BorderLayout.WEST);r.add(v,BorderLayout.CENTER);p.add(r);p.add(Box.createVerticalStrut(5));}return p;}
 private static String safe(Object x){return x==null||x.toString().isBlank()?"Chưa cập nhật":x.toString();}private static String fmt(java.time.LocalDate d){return d==null?"Chưa cập nhật":F.format(d);}private void open(Card c){new InsuranceDialog(SwingUtilities.getWindowAncestor(this),session,bus,c).setVisible(true);load();}
 private void load(){new SwingWorker<java.util.List<Card>,Void>(){protected java.util.List<Card> doInBackground(){String st=filter.getSelectedIndex()==0?"":(String)filter.getSelectedItem();return bus.find(session,search.getText(),st);}protected void done(){try{model.setRowCount(0);for(Card c:get()){bus.refreshExpired(session,c);model.addRow(new Object[]{c.id(),c.patientId()+" - "+c.patientName(),c.facility(),fmt(c.fromDate())+" - "+fmt(c.toDate()),c.coverage()+"%",c.status(),c});}hovered=null;showEmpty();}catch(Exception e){UIStyle.showError(InsurancePanel.this,e.getCause()==null?e.getMessage():e.getCause().getMessage());}}}.execute();}
}
